// Command bundlegen bundles the overlay runtime's TypeScript into
// web/bundle.js with the esbuild Go API (Code-ADR-0016 section 2,
// ADR-0019 section 2): no Node.js, the esbuild version pinned in
// go.mod, the checked-in bundle regenerated by go generate. esbuild is
// imported by this generator only, not by the core binary.
package main

import (
	"fmt"
	"os"

	"github.com/evanw/esbuild/pkg/api"
)

func main() {
	result := api.Build(api.BuildOptions{
		EntryPoints:       []string{"runtime/src/main.ts"},
		Outfile:           "web/bundle.js",
		Bundle:            true,
		MinifyWhitespace:  true,
		MinifyIdentifiers: true,
		MinifySyntax:      true,
		Platform:          api.PlatformBrowser,
		Target:            api.ES2020,
		Format:            api.FormatIIFE,
	})
	for _, e := range result.Errors {
		fmt.Fprintf(os.Stderr, "bundlegen: %s\n", e.Text)
	}
	if len(result.Errors) > 0 {
		os.Exit(1)
	}
}
